void abort(void);
void exit(int);

int k = 0;

int main(void) {
  int i;
  int j;

  for (i = 0; i < 2; i++) {
    if (k) {
      if (j != 2)
        abort();
    } else {
      j = 2;
      k++;
    }
  }
  exit(0);
}


